create extension if not exists pgcrypto;
create type public.user_role as enum ('admin');
create type public.pricing_type as enum ('fixed','per_unit','hourly','daily','tiered','custom');
create type public.quotation_status as enum ('new','under_review','approved','sent','accepted','declined','expired','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.user_role not null default 'admin', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.services (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', category text not null default 'General', image_path text, pricing_type public.pricing_type not null default 'custom', base_price bigint not null default 0 check (base_price >= 0), unit_name text, options jsonb not null default '[]'::jsonb, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, phone text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quotations (id uuid primary key default gen_random_uuid(), reference text not null unique, customer_id uuid not null references public.customers(id), status public.quotation_status not null default 'new', currency text not null default 'ZMW', subtotal bigint not null default 0, additional_charges bigint not null default 0, discount_amount bigint not null default 0, tax_amount bigint not null default 0, total_amount bigint not null default 0, customer_notes text not null default '', admin_notes text not null default '', service_location text, valid_until date, submitted_at timestamptz not null default now(), approved_at timestamptz, sent_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quotation_items (id uuid primary key default gen_random_uuid(), quotation_id uuid not null references public.quotations(id) on delete cascade, service_id uuid references public.services(id) on delete set null, description_snapshot text not null, quantity numeric(12,2) not null check (quantity > 0), unit_name text, unit_price bigint not null check (unit_price >= 0), options_snapshot jsonb not null default '[]'::jsonb, line_total bigint not null check (line_total >= 0), created_at timestamptz not null default now());
create table public.quotation_versions (id uuid primary key default gen_random_uuid(), quotation_id uuid not null references public.quotations(id) on delete cascade, version_number integer not null check (version_number > 0), snapshot_json jsonb not null, pdf_storage_path text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(quotation_id, version_number));
create table public.email_logs (id uuid primary key default gen_random_uuid(), quotation_id uuid references public.quotations(id) on delete set null, recipient text not null, email_type text not null, status text not null, provider_message_id text, error_message text, attempt_count integer not null default 0, created_at timestamptz not null default now(), sent_at timestamptz);
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create sequence public.quotation_reference_seq;
create index quotations_status_idx on public.quotations(status); create index quotations_submitted_idx on public.quotations(submitted_at desc); create index customers_email_idx on public.customers(email); create index email_logs_status_idx on public.email_logs(status);
create or replace function public.is_admin() returns boolean language sql stable security invoker set search_path = public as $$ select exists(select 1 from public.profiles where id = auth.uid() and role = 'admin'::public.user_role) $$;
create or replace function public.next_quotation_reference() returns text language plpgsql security definer set search_path = public as $$ declare n bigint; begin n := nextval('public.quotation_reference_seq'); return 'JA-QT-' || to_char(current_date, 'YYYY') || '-' || lpad(n::text, 4, '0'); end; $$;
alter table public.profiles enable row level security; alter table public.services enable row level security; alter table public.customers enable row level security; alter table public.quotations enable row level security; alter table public.quotation_items enable row level security; alter table public.quotation_versions enable row level security; alter table public.email_logs enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_admin on public.profiles for select to authenticated using (id = auth.uid() or public.is_admin());
create policy services_public_active on public.services for select to anon, authenticated using (is_active or public.is_admin());
create policy services_admin_write on public.services for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy customers_admin on public.customers for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy quotations_admin on public.quotations for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy quotation_items_admin on public.quotation_items for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy quotation_versions_admin on public.quotation_versions for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy email_logs_admin on public.email_logs for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy audit_logs_admin on public.audit_logs for all to authenticated using (public.is_admin()) with check (public.is_admin());
revoke all on public.next_quotation_reference() from public; grant execute on function public.next_quotation_reference() to service_role;
